🐛 Bug

fuseLoops failed to fuse loops if a reduce op exists. The problem is that for reduce ops, it detected a fake ReadAfterWrite dependence between loop iterations and therefore returned without applying fuse transformation. But the detection algorithm is wrong and there is no data dependence between loop iterations.
To Reproduce
Test to reproduce the behavior:
  1 import torch
  2 
  3 class kernel_arena_scope(object):
  4     def __enter__(self):
  5         self.scope = torch._C._te.KernelScope()
  6 
  7     def __exit__(self, typ, val, traceback):
  8         self.scope = None
  9 
 10 with kernel_arena_scope():
 11     f32 = torch._C._te.Dtype.Float
 12     i32 = torch._C._te.Dtype.Int
 13 
 14     M, K, N = 64, 64, 64
 15     Mte, Kte, Nte = [torch._C._te.ExprHandle.int(x) for x in [M, K, N]]
 16     A = torch._C._te.Placeholder('A', f32, [Mte, Kte])
 17     B = torch._C._te.Placeholder('B', f32, [Kte, Nte])
 18 
 19     def get_dim_args(dims):
 20         dim_args = []
 21         for dim in dims:
 22             dim_args.append(torch._C._te.DimArg(dim, 'i' + str(len(dim_args))))
 23         return dim_args
 24 
 25     def compute(dims):
 26         m, n, k = dims[0], dims[1], dims[2]
 27         return A.load([m, k]) * B.load([k, n])
 28 
 29     C = torch._C._te.Reduce('C',
 30                 get_dim_args([Mte, Nte]),
 31                 torch._C._te.Sum(),
 32                 compute,
 33                 get_dim_args([Kte]),
 34                 )
 35     D = torch._C._te.Compute(
 36             'D',
 37             get_dim_args([Mte, Nte]),
 38             lambda m, n: C.load([m, n])
 39             )
 40     stmt = torch._C._te.Block([C.stmt(), D.stmt()])
 41     loopnest = torch._C._te.LoopNest(stmt, [D.buf()])
 42     print(f"original stmt: {loopnest}")
 43     cm, cn, ck = loopnest.get_loops_for(C)
 44     dm, dn = loopnest.get_loops_for(D)
 45     print(cm, dm)                                                                                                                                                             
 46     loopnest.fuse_loops([cm, dm])
 47     print(f"after fuse: {loopnest}")


