🐛 Bug

Summary
For aten ops, we know "AutoCast"'s  priority is higher than "Tracer".
But for custom ops, "Tracer" will get the highest priority.
Consequence
The dtype cast under "autocast" context cannot be recorded on graph.
Example
Suppose we have custom functions below (just return the first input of it)
at::Tensor AtenIpexTypeExt::my_custom_op(
    const at::Tensor &input1, 
    const at::Tensor &input2) {
  return input1;
}

static auto dispatch = torch::RegisterOperators()
        .op("torch_ipex::my_custom_op", &torch_ipex::my_custom_op);
}

We register an auto-cast function for this custom op to convert the inputs (like convert to at::BFloat16)
at::Tensor AtenIpexTypeExt::my_custom_op(
    const at::Tensor &input1, 
    const at::Tensor &input2) {
  c10::impl::ExcludeDispatchKeyGuard no_autocastCPU(DispatchKey::AutocastCPU);
  static auto op = torch::Dispatcher::singleton()
    .findSchemaOrThrow("torch_ipex::my_custom_op", "")
    .typed<decltype(my_custom_op)>();
  auto target_type = get_autocast_dtype();
  auto casted_i1 = cpu_cached_cast(target_type, input1);
  auto casted_i2 = cpu_cached_cast(target_type, input2);
  return op.call(casted_i1, casted_i2);
}

TORCH_LIBRARY_IMPL(torch_ipex, AutocastCPU, m){
  m.impl("my_custom_op", torch_ipex::autocast::my_custom_op);
}

And if we run trace under amp context
input1 = torch.rand(3,3)
input2 = torch.rand(3,3)

class M(nn.Module):
    def __init__(self):
        super(M, self).__init__()

    def forward(self, x1, x2):
        return torch.ops.torch_ipex.my_custom_op(x1,x2)

my_custom_mod = M()

with AMP_ENABLED, torch.no_grad():
    traced= torch.jit.trace(my_custom_mod, [input1, input2])

print(traced.graph)


